-- Phase 4 purchase and supplier engine. SQL-first because RLS and immutable rules are security-critical.
create type purchase_match_status as enum ('PENDING','MATCHED','MISMATCH','APPROVED_EXCEPTION','DISPUTED');

create table supplier_categories (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), code text not null, name text not null, archived_at timestamptz, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,code));
create table suppliers (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), category_id uuid, code text not null, legal_name text not null, display_name text not null, contact_person text, mobile_number text, email text, tax_registration_number text, tax_identity_number text, payment_terms_days integer not null default 0 check(payment_terms_days>=0), credit_limit numeric(20,4) not null default 0 check(credit_limit>=0), default_currency text not null check(length(default_currency)=3), active boolean not null default false, notes text, attachment_references jsonb not null default '[]', archived_at timestamptz, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,code), foreign key(company_id,category_id) references supplier_categories(company_id,id));
create table supplier_contacts (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), supplier_id uuid not null, name text not null, role text, phone text, email text, is_primary boolean not null default false, archived_at timestamptz, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,supplier_id) references suppliers(company_id,id));
create table supplier_addresses (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), supplier_id uuid not null, address_type text not null check(address_type in ('BILLING','PICKUP','SHIPPING','OTHER')), line1 text not null, line2 text, city text not null, region text, postal_code text, country_code text not null, is_primary boolean not null default false, archived_at timestamptz, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,supplier_id) references suppliers(company_id,id));
create table supplier_bank_accounts (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), supplier_id uuid not null, masked_account text not null, bank_name text not null, encrypted_payload text not null, key_reference text not null, active boolean not null default true, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,supplier_id) references suppliers(company_id,id));

create table purchase_requisitions (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), reference_number text not null, status text not null default 'DRAFT', business_date date not null, required_date date, warehouse_id uuid, notes text, submitted_at timestamptz, approved_at timestamptz, approved_by uuid references users(id), decision_reason text, decided_at timestamptz, decided_by uuid references users(id), version integer not null default 1, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,reference_number), foreign key(company_id,warehouse_id) references warehouses(company_id,id));
create table purchase_requisition_lines (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), requisition_id uuid not null, variant_id uuid not null, packaging_level_id uuid, package_quantity numeric(24,8) not null check(package_quantity>0), conversion_snapshot numeric(24,8) not null check(conversion_snapshot>0), base_quantity numeric(24,8) not null check(base_quantity>0), remarks text, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,requisition_id) references purchase_requisitions(company_id,id), foreign key(company_id,variant_id) references product_variants(company_id,id), foreign key(company_id,packaging_level_id) references product_packaging_levels(company_id,id));
create table purchase_orders (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), supplier_id uuid not null, requisition_id uuid, reference_number text not null, status text not null default 'DRAFT', business_date date not null, currency text not null check(length(currency)=3), expected_delivery_date date, subtotal numeric(20,4) not null check(subtotal>=0), discount_total numeric(20,4) not null default 0 check(discount_total>=0), tax_total numeric(20,4) not null default 0 check(tax_total>=0), grand_total numeric(20,4) not null check(grand_total>=0), submitted_at timestamptz, approved_at timestamptz, approved_by uuid references users(id), notes text, version integer not null default 1, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,reference_number), foreign key(company_id,supplier_id) references suppliers(company_id,id), foreign key(company_id,requisition_id) references purchase_requisitions(company_id,id));
create table purchase_order_lines (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), purchase_order_id uuid not null, variant_id uuid not null, packaging_level_id uuid, warehouse_id uuid not null, package_quantity numeric(24,8) not null check(package_quantity>0), conversion_snapshot numeric(24,8) not null check(conversion_snapshot>0), base_quantity numeric(24,8) not null check(base_quantity>0), received_base_quantity numeric(24,8) not null default 0 check(received_base_quantity>=0), returned_base_quantity numeric(24,8) not null default 0 check(returned_base_quantity>=0), invoiced_base_quantity numeric(24,8) not null default 0 check(invoiced_base_quantity>=0), package_unit_price numeric(20,4) not null check(package_unit_price>=0), discount_amount numeric(20,4) not null default 0 check(discount_amount>=0), tax_amount numeric(20,4) not null default 0 check(tax_amount>=0), line_total numeric(20,4) not null check(line_total>=0), created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,purchase_order_id) references purchase_orders(company_id,id), foreign key(company_id,variant_id) references product_variants(company_id,id), foreign key(company_id,packaging_level_id) references product_packaging_levels(company_id,id), foreign key(company_id,warehouse_id) references warehouses(company_id,id));
create table purchase_order_approvals (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), purchase_order_id uuid not null, decision text not null check(decision in ('APPROVED','REJECTED','RETURNED')), reason text, decided_at timestamptz not null default now(), created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,purchase_order_id) references purchase_orders(company_id,id));

create table goods_receipts (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), purchase_order_id uuid not null, supplier_id uuid not null, warehouse_id uuid not null, reference_number text not null, status text not null default 'DRAFT', business_date date not null, inventory_transaction_id uuid, posted_at timestamptz, posted_by uuid references users(id), notes text, version integer not null default 1, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,reference_number), foreign key(company_id,purchase_order_id) references purchase_orders(company_id,id), foreign key(company_id,supplier_id) references suppliers(company_id,id), foreign key(company_id,warehouse_id) references warehouses(company_id,id), foreign key(company_id,inventory_transaction_id) references inventory_transactions(company_id,id));
create table goods_receipt_lines (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), goods_receipt_id uuid not null, purchase_order_line_id uuid not null, variant_id uuid not null, packaging_level_id uuid, warehouse_id uuid not null, location_id uuid, package_quantity numeric(24,8) not null check(package_quantity>0), conversion_snapshot numeric(24,8) not null check(conversion_snapshot>0), accepted_base_quantity numeric(24,8) not null check(accepted_base_quantity>=0), rejected_base_quantity numeric(24,8) not null default 0 check(rejected_base_quantity>=0), inventory_transaction_line_id uuid, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,goods_receipt_id) references goods_receipts(company_id,id), foreign key(company_id,purchase_order_line_id) references purchase_order_lines(company_id,id), foreign key(company_id,variant_id) references product_variants(company_id,id), foreign key(company_id,packaging_level_id) references product_packaging_levels(company_id,id), foreign key(company_id,warehouse_id) references warehouses(company_id,id), foreign key(company_id,location_id) references warehouse_locations(company_id,id), foreign key(company_id,inventory_transaction_line_id) references inventory_transaction_lines(company_id,id));
create table goods_receipt_batches (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), goods_receipt_line_id uuid not null, batch_number text not null, expiry_date date, base_quantity numeric(24,8) not null check(base_quantity>0), created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,goods_receipt_line_id) references goods_receipt_lines(company_id,id));
create table goods_receipt_serial_numbers (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), goods_receipt_line_id uuid not null, variant_id uuid not null, serial_number text not null, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,variant_id,serial_number), foreign key(company_id,goods_receipt_line_id) references goods_receipt_lines(company_id,id));

create table purchase_invoices (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), supplier_id uuid not null, purchase_order_id uuid, reference_number text not null, supplier_invoice_number text not null, status text not null default 'DRAFT', match_status purchase_match_status not null default 'PENDING', business_date date not null, currency text not null check(length(currency)=3), invoice_total numeric(20,4) not null check(invoice_total>=0), outstanding_amount numeric(20,4) not null check(outstanding_amount>=0), attachment_references jsonb not null default '[]', notes text, version integer not null default 1, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,supplier_id,supplier_invoice_number), foreign key(company_id,supplier_id) references suppliers(company_id,id), foreign key(company_id,purchase_order_id) references purchase_orders(company_id,id));
create table purchase_invoice_lines (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), purchase_invoice_id uuid not null, purchase_order_line_id uuid, goods_receipt_line_id uuid, variant_id uuid not null, invoiced_base_quantity numeric(24,8) not null check(invoiced_base_quantity>0), package_unit_price numeric(20,4) not null check(package_unit_price>=0), tax_amount numeric(20,4) not null default 0, line_total numeric(20,4) not null, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,purchase_invoice_id) references purchase_invoices(company_id,id), foreign key(company_id,purchase_order_line_id) references purchase_order_lines(company_id,id), foreign key(company_id,goods_receipt_line_id) references goods_receipt_lines(company_id,id), foreign key(company_id,variant_id) references product_variants(company_id,id));
create table purchase_invoice_matches (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), purchase_invoice_line_id uuid not null, purchase_order_line_id uuid, goods_receipt_line_id uuid, status purchase_match_status not null, ordered_base_quantity numeric(24,8), received_base_quantity numeric(24,8), invoiced_base_quantity numeric(24,8), ordered_package_price numeric(20,4), invoiced_package_price numeric(20,4), issues jsonb not null default '[]', approved_by uuid references users(id), approved_at timestamptz, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,purchase_invoice_line_id) references purchase_invoice_lines(company_id,id), foreign key(company_id,purchase_order_line_id) references purchase_order_lines(company_id,id), foreign key(company_id,goods_receipt_line_id) references goods_receipt_lines(company_id,id));

create table purchase_returns (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), supplier_id uuid not null, goods_receipt_id uuid not null, reference_number text not null, status text not null default 'DRAFT', business_date date not null, reason text not null, credit_note_reference text, inventory_transaction_id uuid, posted_at timestamptz, posted_by uuid references users(id), notes text, version integer not null default 1, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,reference_number), foreign key(company_id,supplier_id) references suppliers(company_id,id), foreign key(company_id,goods_receipt_id) references goods_receipts(company_id,id), foreign key(company_id,inventory_transaction_id) references inventory_transactions(company_id,id));
create table purchase_return_lines (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), purchase_return_id uuid not null, goods_receipt_line_id uuid not null, variant_id uuid not null, warehouse_id uuid not null, location_id uuid, package_quantity numeric(24,8) not null check(package_quantity>0), conversion_snapshot numeric(24,8) not null check(conversion_snapshot>0), base_quantity numeric(24,8) not null check(base_quantity>0), inventory_transaction_line_id uuid, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,purchase_return_id) references purchase_returns(company_id,id), foreign key(company_id,goods_receipt_line_id) references goods_receipt_lines(company_id,id), foreign key(company_id,variant_id) references product_variants(company_id,id), foreign key(company_id,warehouse_id) references warehouses(company_id,id), foreign key(company_id,location_id) references warehouse_locations(company_id,id), foreign key(company_id,inventory_transaction_line_id) references inventory_transaction_lines(company_id,id));
create table purchase_return_batches (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), purchase_return_line_id uuid not null, batch_number text not null, expiry_date date, base_quantity numeric(24,8) not null check(base_quantity>0), created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,purchase_return_line_id) references purchase_return_lines(company_id,id));
create table purchase_return_serial_numbers (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), purchase_return_line_id uuid not null, serial_number text not null, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,purchase_return_line_id,serial_number), foreign key(company_id,purchase_return_line_id) references purchase_return_lines(company_id,id));

create table landed_costs (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), goods_receipt_id uuid not null, reference_number text not null, status text not null default 'DRAFT', business_date date not null, allocation_method text not null check(allocation_method in ('QUANTITY','WEIGHT','VOLUME','ITEM_VALUE','MANUAL')), currency text not null, total_amount numeric(20,4) not null check(total_amount>=0), notes text, version integer not null default 1, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,reference_number), foreign key(company_id,goods_receipt_id) references goods_receipts(company_id,id));
create table landed_cost_lines (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), landed_cost_id uuid not null, cost_type text not null, description text, amount numeric(20,4) not null check(amount>=0), created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,landed_cost_id) references landed_costs(company_id,id));
create table landed_cost_allocations (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), landed_cost_id uuid not null, landed_cost_line_id uuid not null, goods_receipt_line_id uuid not null, basis_quantity numeric(24,8), basis_value numeric(20,4), allocated_amount numeric(20,4) not null check(allocated_amount>=0), effective_cost_per_base_unit numeric(20,4), created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,landed_cost_id) references landed_costs(company_id,id), foreign key(company_id,landed_cost_line_id) references landed_cost_lines(company_id,id), foreign key(company_id,goods_receipt_line_id) references goods_receipt_lines(company_id,id));
create table supplier_payments (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), supplier_id uuid not null, reference_number text not null, status text not null default 'DRAFT', business_date date not null, payment_method text not null, currency text not null check(length(currency)=3), amount numeric(20,4) not null check(amount>0), payment_reference text not null, approved_by uuid references users(id), approved_at timestamptz, notes text, version integer not null default 1, created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), unique(company_id,reference_number), foreign key(company_id,supplier_id) references suppliers(company_id,id));
create table supplier_payment_allocations (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id), supplier_payment_id uuid not null, purchase_invoice_id uuid not null, allocated_amount numeric(20,4) not null check(allocated_amount>0), created_at timestamptz not null default now(), created_by uuid references users(id), updated_at timestamptz not null default now(), updated_by uuid references users(id), unique(company_id,id), foreign key(company_id,supplier_payment_id) references supplier_payments(company_id,id), foreign key(company_id,purchase_invoice_id) references purchase_invoices(company_id,id));

create index suppliers_company_name_idx on suppliers(company_id,display_name) where archived_at is null;
create index purchase_orders_company_supplier_status_idx on purchase_orders(company_id,supplier_id,status,business_date);
create index purchase_order_lines_company_order_idx on purchase_order_lines(company_id,purchase_order_id);
create index goods_receipts_company_order_idx on goods_receipts(company_id,purchase_order_id,business_date);
create index goods_receipt_lines_company_receipt_idx on goods_receipt_lines(company_id,goods_receipt_id);
create index purchase_invoices_company_supplier_status_idx on purchase_invoices(company_id,supplier_id,status,business_date);
create index purchase_returns_company_receipt_idx on purchase_returns(company_id,goods_receipt_id);
create index landed_costs_company_receipt_idx on landed_costs(company_id,goods_receipt_id);
create index supplier_payments_company_supplier_idx on supplier_payments(company_id,supplier_id,business_date);
create index supplier_payment_allocations_company_invoice_idx on supplier_payment_allocations(company_id,purchase_invoice_id);

create or replace function reject_purchase_history_mutation() returns trigger language plpgsql as $$ begin raise exception 'posted purchase history is append-only'; end $$;
create trigger purchase_order_approvals_immutable before update or delete on purchase_order_approvals for each row execute function reject_purchase_history_mutation();
create trigger purchase_invoice_matches_immutable before update or delete on purchase_invoice_matches for each row execute function reject_purchase_history_mutation();
create trigger supplier_payment_allocations_immutable before update or delete on supplier_payment_allocations for each row execute function reject_purchase_history_mutation();
create trigger landed_cost_allocations_immutable before update or delete on landed_cost_allocations for each row execute function reject_purchase_history_mutation();

DO $purchase_rls$
DECLARE table_name text;
BEGIN
  FOREACH table_name IN ARRAY ARRAY['supplier_categories','suppliers','supplier_contacts','supplier_addresses','supplier_bank_accounts','purchase_requisitions','purchase_requisition_lines','purchase_orders','purchase_order_lines','purchase_order_approvals','goods_receipts','goods_receipt_lines','goods_receipt_batches','goods_receipt_serial_numbers','purchase_invoices','purchase_invoice_lines','purchase_invoice_matches','purchase_returns','purchase_return_lines','purchase_return_batches','purchase_return_serial_numbers','landed_costs','landed_cost_lines','landed_cost_allocations','supplier_payments','supplier_payment_allocations']
  LOOP
    EXECUTE format('alter table %I enable row level security',table_name);
    EXECUTE format('alter table %I force row level security',table_name);
    EXECUTE format('create policy %I on %I using (company_id = current_setting(''app.current_company_id'',true)::uuid) with check (company_id = current_setting(''app.current_company_id'',true)::uuid)',table_name||'_tenant_policy',table_name);
  END LOOP;
END $purchase_rls$;